module serial2parallel (
	input clk, rst_n, din_valid, din_serial,
	output reg [7:0] dout_parallel, dout_valid
);

	reg [3:0] cnt;
	integer COUNTER_MAX = 8;

	always@(posedge clk or negedge rst_n)begin
		if(!rst_n)begin
			cnt <= 0;
			dout_parallel <= 0;
			dout_valid <= 0;
		end
		else begin
			if(din_valid && cnt<COUNTER_MAX)begin
				dout_parallel[cnt] <= din_serial;
				cnt <= cnt + 1;
			end

			if(cnt>=COUNTER_MAX)dout_valid <= 1;
			else dout_valid <= 0;

		end
	end

endmodule
